    :root {
        --accent1: #9b59b6;
        --accent2: #c084fc;
        --theme-bg1: #000000;
        --theme-bg2: #b700ff;
    }

    html,
    body {
        margin: 0;
        padding: 0;
        min-height: 100%;
        overflow-x: hidden;
        font-family: "Grandstander", cursive;
        color: white;
    }

    /* =========================
       BACKGROUND
    ========================= */

    #bg {
        position: fixed;
        inset: 0;
        background: linear-gradient(
            135deg,
            var(--theme-bg1),
            var(--theme-bg2)
        );
        background-position: center;
        background-size: cover;
        background-repeat: no-repeat;
        overflow: hidden;
        z-index: 0;
    }

    .background-video {
        position: absolute;
        inset: 0;
        width: 100%;
        height: 100%;
        object-fit: cover;
        pointer-events: none;
        z-index: 0;
    }

    /* =========================
       STARS
    ========================= */

    #starContainer {
        position: fixed;
        inset: 0;
        z-index: 1;
        pointer-events: none;
    }

    .star {
        position: absolute;
        border-radius: 50%;
        background: white;
        opacity: 0.4;
        animation: twinkle infinite ease-in-out;
    }

    @keyframes twinkle {
        0%, 100% {
            opacity: 0.2;
            transform: scale(1);
        }

        50% {
            opacity: 0.9;
            transform: scale(1.4);
        }
    }

    /* =========================
       CONTENT
    ========================= */

    .page {
        position: relative;
        z-index: 2;
        display: flex;
        justify-content: center;
        padding: 40px 0;
    }

    .panel {
        width: min(600px, 90vw);
        padding: 30px;
        border-radius: 18px;
        background: transparent;
        backdrop-filter: none;
        box-shadow: none;
        border: none;
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 12px;
    }

    /* =========================
       BUTTONS
    ========================= */

    .panel button {
        width: 100%;
        padding: 12px 14px;
        border-radius: 14px;
        border: 1px solid rgba(255, 255, 255, 0.12);
        background: rgba(73, 73, 73, 0.144);
        color: white;
        cursor: pointer;
        transition: 0.2s;
        font-family: "Grandstander", cursive;
    }

    .panel button:hover {
        background: rgba(255, 255, 255, 0.16);
        transform: translateY(-2px);
    }

    .panel button:active {
        transform: scale(0.98);
    }

    /* =========================
       GROUPS
    ========================= */

    .group {
        width: 100%;
        padding: 12px;
        border-radius: 20px;
        background: rgba(0, 0, 0, 0.096);
        margin: 20px 0;
        font-family: "Grandstander", cursive;
        box-sizing: border-box;
    }

    .group h2 {
        text-align: center;
    }

    /* =========================
       SMALL BUTTONS
    ========================= */

    .small {
        width: 42px;
        height: 30px;
        padding: 0;
        border-radius: 8px;
    }

    .nf {
        background-color: rgba(255, 255, 255, 0.151);
        border-color: white;
        color: white;
        font-family: "Grandstander", cursive;
    }

    .random-input {
        font-family: "Grandstander", cursive;
        background-color: rgba(255, 255, 255, 0.18);
    }

    /* =========================
       INPUTS
    ========================= */

    input,
    select {
        width: 100%;
        padding: 10px;
        border-radius: 10px;
        border: none;
        outline: none;
        text-align: center;
        box-sizing: border-box;
        font-family: "Grandstander", cursive;
    }

    /* =========================
       SETTINGS
    ========================= */

    .settings-grid {
        display: grid;
        grid-template-columns: repeat(
            auto-fit,
            minmax(100px, 1fr)
        );
        gap: 12px;
        width: 100%;
        max-width: 620px;
        height: 420px;
        overflow-y: auto;
        overflow-x: hidden;
        padding-right: 6px;
        margin: auto;
    }

    .setting-btn {
        max-width: 170px;
        min-height: 70px;
        border-radius: 14px;
        display: flex;
        align-items: center;
        justify-content: center;
        flex-direction: column;
        text-align: center;
        font-size: 12px;
        gap: 3px;
        font-family: "Grandstander", cursive;
    }

    .setting-btn:hover {
        transform: translateY(-2px);
    }

    .setting-btn.active {
        border: 1px solid rgba(110, 190, 255, 0.95);
        box-shadow:
            0 0 12px rgba(110, 190, 255, 0.35),
            0 0 24px rgba(110, 190, 255, 0.18),
            inset 0 0 12px rgba(110, 190, 255, 0.08);
        background: rgba(255, 255, 255, 0.08);
        transform: translateY(-2px);
    }

    .button-container {
        display: flex;
        flex-wrap: wrap;
        justify-content: center;
        gap: 12px;
        max-height: 300px;
        overflow-y: auto;
        overflow-x: hidden;
        padding: 10px;
    }

    .button-container button {
        flex: 1 1 120px;
        min-width: 120px;
        padding: 12px;
        border-radius: 12px;
        border: 1px solid rgba(255, 255, 255, 0.12);
        background: rgba(255, 255, 255, 0.06);
        color: white;
        cursor: pointer;
        transition: 0.2s;
        font-family: "Grandstander", cursive;
    }

    .button-container button:hover {
        transform: translateY(-2px);
        background: rgba(255, 255, 255, 0.12);
    }

    /* =========================
       THEME BUTTONS
    ========================= */

    .theme-btn {
        min-height: 75px !important;
        font-size: 14px !important;
        font-weight: 600;
    }

    .theme-preview {
        width: 45px;
        height: 15px;
        border-radius: 20px;
        margin-bottom: 4px;
    }

    .theme-default .theme-preview {
        background: linear-gradient(90deg, #000, #b700ff);
    }

    .theme-girly .theme-preview {
        background: linear-gradient(90deg, #ff69b4, #ffb6d9);
    }

    .theme-hacker .theme-preview {
        background: linear-gradient(90deg, #001a00, #00ff55);
    }

    .theme-ocean .theme-preview {
        background: linear-gradient(90deg, #001f3f, #00aaff);
    }

    .theme-forest .theme-preview {
        background: linear-gradient(90deg, #071a0b, #238636);
    }

    .theme-sunset .theme-preview {
        background: linear-gradient(90deg, #ff512f, #dd2476);
    }

    .theme-purple .theme-preview {
        background: linear-gradient(90deg, #4b0082, #b026ff);
    }

    .theme-cyber .theme-preview {
        background: linear-gradient(90deg, #ff00cc, #3333ff);
    }

    .theme-red .theme-preview {
        background: linear-gradient(90deg, #3a0000, #ff2020);
    }

    .theme-midnight .theme-preview {
        background: linear-gradient(90deg, #020024, #090979);
    }

    .theme-ice .theme-preview {
        background: linear-gradient(90deg, #003b46, #66e6ff);
    }

    .theme-gold .theme-preview {
        background: linear-gradient(90deg, #3d2800, #ffd700);
    }

    .theme-cherry .theme-preview {
        background: linear-gradient(90deg, #250008, #d90429);
    }

    .theme-lavender .theme-preview {
        background: linear-gradient(90deg, #301934, #c77dff);
    }

    .theme-neon .theme-preview {
        background: linear-gradient(90deg, #00ffea, #ff00ff);
    }

    .theme-coffee .theme-preview {
        background: linear-gradient(90deg, #1b0f08, #8b4513);
    }

    .theme-emerald .theme-preview {
        background: linear-gradient(90deg, #001f16, #00c878);
    }

    /* =========================
       OVERLAY
    ========================= */

    #overlay {
        position: fixed;
        inset: 0;
        z-index: 9999999999;
        background: black;
        opacity: 1;
        transition: opacity 0.6s ease;
    }

    #overlay.hide {
        opacity: 0;
        pointer-events: none;
    }

/* =========================
   DARK BACKGROUND OVERLAY
========================= */

#bg::after {
    content: "";
    position: absolute;
    inset: 0;

    background: rgba(0, 0, 0, 0.214);

    pointer-events: none;
    z-index: 1;
}

/* Keep videos behind the dark overlay */
.background-video {
    z-index: 0 !important;
}

/* Content stays above everything */
.page {
    z-index: 3 !important;
}

#starContainer {
    z-index: 2 !important;
}


    #introFrame {
        width: 100%;
        height: 100%;
        border: none;
    }

    #clickLayer {
        position: absolute;
        inset: 0;
        background: transparent;
        cursor: pointer;
    }

    /* =========================
       INACTIVE TAB OVERLAY
    ========================= */

    #inactiveOverlay {
        position: fixed;
        inset: 0;
        background: #000;
        z-index: 999999999;
        display: none;
        pointer-events: none;
    }

    #inactiveOverlay.active {
        display: block;
    }
