            bg1: "#00140e",
            bg2: "#006b43"
        }
    };

    /*
     * Apply the currently selected theme.
     *
     * IMPORTANT:
     * The theme is ALWAYS applied, even when the
     * background type is "none".
     *
     * "none" only means:
     * no image / GIF / video.
     *
     * The theme gradient still remains visible.
     */

    function setTheme(themeName) {
        const theme = themes[themeName];

        if (!theme) return;

        localStorage.setItem(
            "selectedTheme",
            themeName
        );

        applyTheme();
        applyBackground();
    }

    function applyTheme() {
        const themeName =
            localStorage.getItem("selectedTheme") ||
            "default";

        const theme =
            themes[themeName] ||
            themes.default;

        document.documentElement.style.setProperty(
            "--accent1",
            theme.accent1
        );

        document.documentElement.style.setProperty(
            "--accent2",
            theme.accent2
        );

        document.documentElement.style.setProperty(
            "--theme-bg1",
            theme.bg1
        );

        document.documentElement.style.setProperty(
            "--theme-bg2",
            theme.bg2
        );

        /*
         * If the user has "None" selected,
         * explicitly show the selected theme gradient.
         *
         * This is the important fix.
         */

        const bg =
            document.getElementById("bg");

        if (bg) {
            const bgType =
                localStorage.getItem("bgType");

            if (
                bgType === "none" ||
                !bgType
            ) {
                bg.style.background =
                    `linear-gradient(
                        135deg,
                        ${theme.bg1},
                        ${theme.bg2}
                    )`;

                bg.style.backgroundImage =
                    `linear-gradient(
                        135deg,
                        ${theme.bg1},
                        ${theme.bg2}
                    )`;

                bg.style.backgroundColor =
                    "transparent";
            }
        }

        updateThemeButtons();
    }

    function updateThemeButtons() {
        const current =
            localStorage.getItem(
                "selectedTheme"
            ) || "default";

        document
            .querySelectorAll("[data-theme]")
            .forEach(button => {
                button.classList.toggle(
                    "active",
                    button.dataset.theme === current
                );
            });
    }
");runInline("

    function setBackground(
        type,
        value = ""
    ) {

        /*
         * Store the background separately
         * from the theme.
         */

        localStorage.setItem(
            "bgType",
            type
        );

        localStorage.setItem(
            "bgValue",
            value
        );

        localStorage.setItem(
            "activeBackground",
            value || type
        );

        applyBackground();
        updateActiveBackgroundButton();
    }

    function updateActiveBackgroundButton() {

        const type =
            localStorage.getItem(
                "bgType"
            ) || "none";

        const value =
            localStorage.getItem(
                "bgValue"
            ) || "";

        document
            .querySelectorAll(
                ".button-container .setting-btn"
            )
            .forEach(button => {

                if (
                    button.hasAttribute(
                        "data-type"
                    )
                ) {

                    button.classList.remove(
                        "active"
                    );

                    const buttonType =
                        button.dataset.type || "";

                    const buttonValue =
                        button.dataset.bg || "";

                    if (
                        buttonType === type &&
                        buttonValue === value
                    ) {
                        button.classList.add(
                            "active"
                        );
                    }
                }
            });
    }

    function applyBackground() {

        let type =
            localStorage.getItem(
                "bgType"
            );

        let value =
            localStorage.getItem(
                "bgValue"
            );

        /*
         * NEW USERS:
         *
         * If no background has ever been
         * selected, use the OMORILAB video.
         */

        if (!type) {

            type = "video";

            value =
                "/background-imgs/OMORILAB ORIGINAL ANIMATION MEME 3333.mp4";

            localStorage.setItem(
                "bgType",
                type
            );

            localStorage.setItem(
                "bgValue",
                value
            );
        }

        const bg =
            document.getElementById("bg");

        if (!bg) return;

        /*
         * Remove old video first.
         */

        const oldVideo =
            bg.querySelector(
                ".background-video"
            );

        if (oldVideo) {
            oldVideo.pause();
            oldVideo.remove();
        }

        /*
         * Clear old background.
         */

        bg.style.background = "none";
        bg.style.backgroundImage = "none";
        bg.style.backgroundColor = "transparent";

        /*
         * =========================
         * NONE
         * =========================
         *
         * IMPORTANT:
         *
         * None does NOT mean white.
         *
         * None means:
         * "Don't use a custom image/video."
         *
         * The selected theme gradient
         * remains visible.
         */

        if (type === "none") {

            const themeName =
                localStorage.getItem(
                    "selectedTheme"
                ) || "default";

            const theme =
                themes[themeName] ||
                themes.default;

            bg.style.background =
                `linear-gradient(
                    135deg,
                    ${theme.bg1},
                    ${theme.bg2}
                )`;

            bg.style.backgroundImage =
                `linear-gradient(
                    135deg,
                    ${theme.bg1},
                    ${theme.bg2}
                )`;

            bg.style.backgroundColor =
                "transparent";

            return;
        }

        /*
         * If there is no value,
         * fall back to the theme.
         */

        if (!value) {

            const themeName =
                localStorage.getItem(
                    "selectedTheme"
                ) || "default";

            const theme =
                themes[themeName] ||
                themes.default;

            bg.style.background =
                `linear-gradient(
                    135deg,
                    ${theme.bg1},
                    ${theme.bg2}
                )`;

            return;
        }

        /*
         * =========================
         * IMAGE
         * =========================
         */

        if (type === "image") {

            bg.style.background =
                `url("${value}") center/cover no-repeat`;

            return;
        }

        /*
         * =========================
         * VIDEO
         * =========================
         */

        if (type === "video") {

            const video =
                document.createElement(
                    "video"
                );

            video.className =
                "background-video";

            video.src = value;

            video.autoplay = true;
            video.loop = true;
            video.muted = true;
            video.defaultMuted = true;
            video.playsInline = true;
            video.preload = "auto";

            video.setAttribute(
                "aria-hidden",
                "true"
            );

            bg.appendChild(video);

            video.play().catch(() => {});

            /*
             * If the video fails,
             * show the selected theme
             * instead of leaving a blank page.
             */

            video.addEventListener(
                "error",
                () => {

                    video.remove();

                    const themeName =
                        localStorage.getItem(
                            "selectedTheme"
                        ) || "default";

                    const theme =
                        themes[themeName] ||
                        themes.default;

                    bg.style.background =
                        `linear-gradient(
                            135deg,
                            ${theme.bg1},
                            ${theme.bg2}
                        )`;

                    bg.style.backgroundImage =
                        `linear-gradient(
                            135deg,
                            ${theme.bg1},
                            ${theme.bg2}
                        )`;
                }
            );

            return;
        }
    }

    /*
     * Apply everything once the page loads.
     */

    document.addEventListener(
        "DOMContentLoaded",
        () => {

            applyTheme();
            applyBackground();
            updateActiveBackgroundButton();
            updateThemeButtons();

        }
    );

