            star.style.top =
                Math.random() *
                window.innerHeight +
                "px";

            star.style.left =
                Math.random() *
                window.innerWidth +
                "px";

            star.style.animationDuration =
                Math.random() * 3 + 2 +
                "s";

            container.appendChild(star);
        }
    }

    createStars();

