    function openBlank() {

        const win =
            window.open(
                "about:blank",
                "_blank"
            );

        if (!win) {

            alert("Popup blocked");
            return;
        }

        const iframe =
            win.document.createElement(
                "iframe"
            );

        iframe.style.width = "100%";
        iframe.style.height = "100%";
        iframe.style.border = "none";

        iframe.src =
            location.href;

        win.document.body.style.margin =
            "0";

        win.document.body.appendChild(
            iframe
        );
    }

