    const inactiveOverlay =
        document.getElementById(
            "inactiveOverlay"
        );

    function updateInactiveOverlay() {

        if (document.hidden) {

            inactiveOverlay.classList.add(
                "active"
            );

        } else {

            inactiveOverlay.classList.remove(
                "active"
            );
        }
    }

    document.addEventListener(
        "visibilitychange",
        updateInactiveOverlay
    );

    window.addEventListener(
        "blur",
        () => {

            inactiveOverlay.classList.add(
                "active"
            );
        }
    );

    window.addEventListener(
        "focus",
        () => {

            if (!document.hidden) {

                inactiveOverlay.classList.remove(
                    "active"
                );
            }
        }
    );

    updateInactiveOverlay();

